mkdir -p /tmp/claude-0/-home-user-Claudinite/4c6e24de-09b6-5ca9-8127-81ee7fdd64b0/scratchpad && cat > /tmp/claude-0/-home-user-Claudinite/4c6e24de-09b6-5ca9-8127-81ee7fdd64b0/scratchpad/consumers.mjs <<'EOF'
// Who, outside packs/claudinite-tasks/, names public/ — and what they take from it.
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';

const ROOT = '/home/user/Claudinite';
const files = execSync('git ls-files', { cwd: ROOT, encoding: 'utf8' }).trim().split('\n');

const PUB = 'claudinite-tasks/public/';
const hits = [];
for (const f of files) {
  if (f.startsWith('packs/claudinite-tasks/public/')) continue;
  let txt;
  try { txt = readFileSync(`${ROOT}/${f}`, 'utf8'); } catch { continue; }
  if (!txt.includes(PUB) && !txt.includes("from '../../public/") && !txt.includes("from '../../../public/")) continue;
  const lines = txt.split('\n');
  lines.forEach((l, i) => {
    if (l.includes(PUB) || /from '\.\.(\/\.\.)*\/public\//.test(l)) hits.push({ f, n: i + 1, l: l.trim() });
  });
}

const bucket = (f) => {
  if (f.startsWith('packs/claudinite-tasks/test/')) return 'own-test';
  if (f.startsWith('packs/claudinite-tasks/')) return 'own-pack';
  if (f.startsWith('packs/')) return 'other-pack';
  if (f.startsWith('engine/')) return 'engine';
  if (f.startsWith('.github/')) return 'workflow';
  if (f.startsWith('test/') || f.startsWith('dev/')) return 'repo-test';
  return 'doc/other';
};
const by = {};
for (const h of hits) (by[bucket(h.f)] ??= []).push(h);
for (const [k, v] of Object.entries(by)) {
  console.log(`\n### ${k} (${v.length} lines, ${new Set(v.map(x => x.f)).size} files)`);
  for (const h of v) console.log(`  ${h.f}:${h.n}  ${h.l.slice(0, 150)}`);
}
EOF
cd /home/user/Claudinite && node /tmp/claude-0/-home-user-Claudinite/4c6e24de-09b6-5ca9-8127-81ee7fdd64b0/scratchpad/consumers.mjs 2>&1 | head -120

