    const pf = PUBDIR + pm[1];
    if (!src.has(pf)) continue;
    const set = roots.get(pf) ?? roots.set(pf, new Set()).get(pf);
    (consumers.get(pf) ?? consumers.set(pf, new Set()).get(pf)).add(f);
    const nm = l.match(/(?:import|export)\s*\{([^}]*)\}/);
