const key = (f, s) => `${f}#${s}`;
const seen = new Set();
const fileLevel = new Map();
const liveSymbols = new Map(); // file -> Set
const queue = [];

function addSym(file, sym, level) {
  if (!file || !src.has(file)) return;
  if (!fileLevel.has(file) || fileLevel.get(file) > level) fileLevel.set(file, level);
  const k = key(file, sym);
  if (seen.has(k)) return;
  seen.add(k);
