  } else {
    const exp = mod.exports.get(sym);
    if (exp && (exp.kind === 'reexport' || exp.kind === 'ns')) {
      addSym(exp.file, exp.kind === 'ns' ? '*' : exp.orig, level + 1);
      continue;
    }
