      : String(m.names.length);
    const unread = m.names.filter((n) => !m.used.has(n));
    return `| \`${m.name}\` | ${published} | ${m.used.size || '—'} | ${unread.length ? unread.map((n) => `\`${n}\``).join(', ') : '—'} | ${cell(consumerCell(m.consumers))} |`;
