1	// What a pack's `public/` folder actually publishes, and who outside the pack reads it.
2	//
3	// A published surface is a promise, and a promise nobody renders drifts: this pack's
4	// shelf carried a hand-written table of "modules other packs import" that named an
5	// export (`landPr`) no file has ever had, claimed a folder held only named exports
6	// while nine of its modules opened with `export *`, and listed a consumer for a module
7	// nothing imports. None of that was visible in a diff, because the table and the code
8	// it described were edited in different changes.
9	//
10	// So the table is derived instead. `renderSurfaceReport` is pure over a tree already
11	// read into memory, which keeps the scope assertion honest — a caller that hands it an
12	// empty file set gets an error rather than an empty report that reads as "no surface".
13	//
14	// A WILDCARD is reported as its own state, never expanded into a name list. `export *`
15	// republishes whatever its target exports today, so the surface it publishes is not a
16	// fact about this file at all; rendering the target's current names would state a
17	// promise the folder has not made.
18	
19	// A name a `public/` module publishes, or the wildcard that publishes an unknown set.
20	const WILDCARD = '*';
21	
22	// `export { a, b as c } from '…'` / `export { a, b }` — the named form, which is the
23	// only form that pins a surface. `as` matters: what the outside sees is the alias.
24	const RE_NAMED = /^export\s*\{([^}]*)\}/;
25	const RE_STAR = /^export\s*\*\s*(?:as\s+([\w$]+)\s+)?from\s*['"]([^'"]+)['"]/;
26	const RE_DECL = /^export\s+(?:async\s+)?(?:function\s*\*?\s*([\w$]+)|class\s+([\w$]+)|(?:const|let|var)\s+([\w$]+))/;
27	
28	// An `import {`/`export {` list may wrap across lines, and the path it comes from sits
29	// on the LAST of them; fold each one back onto its opening line before matching, or a
30	// multi-line import reads as a module consumed for no names at all.
31	function logicalLines(text) {
32	  const lines = text.split('\n');
33	  const out = [];
34	  for (let i = 0; i < lines.length; i++) {
35	    let line = lines[i];
36	    while (/^\s*(?:import|export)\s*\{/.test(line) && !line.includes('}') && i + 1 < lines.length) line += ' ' + lines[++i].trim();
37	    out.push(line);
38	  }
39	  return out;
40	}
41	
42	// The names one module publishes. `wildcards` are the `export * from` targets it
43	// opens with; a module carrying both a star and a list publishes MORE than its list,
44	// which is the case worth seeing in a report.
45	export function publishedNames(text) {
46	  const names = [];
47	  const wildcards = [];
48	  for (const line of logicalLines(text)) {
49	    let m;
50	    if ((m = line.match(RE_STAR))) {
51	      if (m[1]) names.push(m[1]);
52	      else wildcards.push(m[2]);
53	    } else if ((m = line.match(RE_DECL))) {
54	      names.push(m[1] || m[2] || m[3]);
55	    } else if ((m = line.match(RE_NAMED))) {
56	      for (const part of m[1].split(',')) {
57	        const n = part.trim().match(/^([\w$]+)(?:\s+as\s+([\w$]+))?$/);
58	        if (n) names.push(n[2] || n[1]);
59	      }
60	    }
61	  }
62	  return { names: [...new Set(names)].sort(), wildcards };
63	}
64	
65	// Who a reference belongs to. The buckets are the ones that carry different weight:
66	// a member's workflow names a path this repo cannot rewrite, another pack's production
67	// code is a live dependency, and a test is only the canon proving its own contract.
68	export function consumerBucket(path, packDir) {
69	  if (path.startsWith(`${packDir}/`)) return 'own pack';
70	  if (path.startsWith('.github/workflows/') || path.endsWith('.yml')) return 'workflow';
71	  const test = path.includes('/test/') || path.endsWith('.test.mjs');
72	  if (path.startsWith('packs/') || path.startsWith('.claudinite/')) return test ? 'pack (test)' : 'pack';
73	  return test ? 'canon (test)' : 'canon';
74	}
75	
76	const BUCKET_ORDER = ['workflow', 'pack', 'pack (test)', 'canon', 'canon (test)', 'own pack'];
77	
78	// How a line reaches the module. A comment naming a path is a MENTION, not a
79	// dependency: it breaks nothing when the surface moves, and counting it as a reader
80	// overstates who the promise is being kept for — which is the one number this report
81	// exists to get right. A `node <path>` line runs the module and takes no name; an
82	// `import` takes names.
83	function reachOf(line) {
84	  if (/^\s*(?:\/\/|\*|#|\|)/.test(line)) return { kind: 'mention', names: [] };
85	  const braces = line.match(/(?:import|export)\s*\{([^}]*)\}\s*from/) || line.match(/\{([^}]*)\}\s*=\s*await\s+import/);
86	  if (braces) return { kind: 'import', names: braces[1].split(',').map((p) => p.trim().match(/^([\w$]+)/)?.[1]).filter(Boolean) };
87	  if (/(?:^|\s)(?:import|export)\s[^{]*from\s*['"]/.test(line) || /\bimport\s*\(/.test(line)) return { kind: 'import', names: [] };
88	  if (/(?:^|\s)node\s/.test(line)) return { kind: 'run', names: [] };
89	  return { kind: 'mention', names: [] };
90	}
91	
92	// Every reference to `<packDir>/public/<file>` anywhere in the tree, however the
93	// referring file spells the path: a member spells it under the mount, a sibling pack
94	// spells it relative. Matching on the tail is what makes one scan cover all three.
95	export function readSurfaceUse({ files, packDir }) {
96	  const pack = packDir.split('/').pop();
97	  const modules = new Map();
98	  for (const [path, text] of files) {
99	    if (!path.startsWith(`${packDir}/public/`)) continue;
100	    const name = path.slice(`${packDir}/public/`.length);
101	    if (name.includes('/')) continue;
102	    modules.set(name, { name, consumers: new Map(), mentions: new Set(), used: new Set(), ...(name.endsWith('.mjs') ? publishedNames(text) : { names: [], wildcards: [] }) });
103	  }
104	  if (!modules.size) throw new Error(`no public/ modules found under ${packDir} — the report would be silently empty`);
105	
106	  const ref = new RegExp(`(?:${pack}/public/|(?:\\.\\./)+public/)([\\w.-]+)`, 'g');
107	  for (const [path, text] of files) {
108	    for (const line of logicalLines(text)) {
109	      for (const m of line.matchAll(ref)) {
110	        const mod = modules.get(m[1]);
111	        if (!mod) continue;
112	        const bucket = consumerBucket(path, packDir);
113	        const reach = reachOf(line);
114	        if (bucket === 'own pack') continue;
115	        if (reach.kind === 'mention') { mod.mentions.add(path); continue; }
116	        (mod.consumers.get(bucket) ?? mod.consumers.set(bucket, new Set()).get(bucket)).add(path);
117	        for (const n of reach.names) mod.used.add(n);
118	      }
119	    }
120	  }
121	  return modules;
122	}
123	
124	const cell = (s) => String(s).replace(/\|/g, '\\|').replace(/\s+/g, ' ').trim();
125	
126	// A consumer list is a summary surface: the packs, not the files, since the file count
127	// tracks how a consumer happens to be split up rather than how much it depends.
128	function consumerCell({ consumers, mentions }) {
129	  const parts = [];
130	  for (const bucket of BUCKET_ORDER) {
131	    const paths = consumers.get(bucket);
132	    if (!paths) continue;
133	    const who = [...new Set([...paths].map((p) => p.startsWith('packs/') ? p.split('/')[1] : p.split('/')[0] || p))].sort();
134	    parts.push(`${bucket}: ${who.join(', ')}`);
135	  }
136	  if (!parts.length) parts.push('**nobody**');
137	  if (mentions.size) parts.push(`${mentions.size} prose mention${mentions.size === 1 ? '' : 's'}`);
138	  return parts.join('; ');
139	}
140	
141	export function renderSurfaceReport({ packDir, files }) {
142	  const modules = [...readSurfaceUse({ files, packDir }).values()].sort((a, b) => a.name.localeCompare(b.name));
143	  const mjs = modules.filter((m) => m.name.endsWith('.mjs'));
144	  const docs = modules.filter((m) => !m.name.endsWith('.mjs'));
145	
146	  const rows = mjs.map((m) => {
147	    const published = m.wildcards.length
148	      ? `${m.names.length} named + \`export *\` from ${m.wildcards.map((w) => `\`${w}\``).join(', ')}`
149	      : String(m.names.length);
150	    const unread = m.names.filter((n) => !m.used.has(n));

