1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { existsSync, readFileSync, writeFileSync, readdirSync } from 'node:fs';
4	import { join, dirname, relative, sep } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	import { renderSurfaceReport, publishedNames, consumerBucket, readSurfaceUse } from '../pack-surface.mjs';
7	
8	// Maintained the way packs/directory.GENERATED.md is (engine-tests/pack-directory.test.mjs):
9	// locally this test rewrites the artifact, under CI it only asserts, so a change that
10	// widens a published surface without regenerating fails in ITS OWN pull request rather
11	// than in a later sweep's.
12	const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
13	const PACK_DIR = 'packs/claudinite-tasks';
14	const REPORT = `${PACK_DIR}/public/SURFACE.GENERATED.md`;
15	
16	const SKIP_DIRS = new Set(['.git', 'node_modules', '.claudinite-cache']);
17	
18	// The tree, read once. Only text the surface can be named from is worth scanning, and
19	// the report itself is excluded — it names every module, so including it would make
20	// every module read as consumed by the canon.
21	function treeText(dir = ROOT, files = new Map()) {
22	  for (const entry of readdirSync(dir, { withFileTypes: true })) {
23	    if (SKIP_DIRS.has(entry.name)) continue;
24	    const abs = join(dir, entry.name);
25	    if (entry.isDirectory()) { treeText(abs, files); continue; }
26	    if (!entry.isFile() || !/\.(mjs|js|json|md|yml|yaml)$/.test(entry.name)) continue;
27	    const rel = relative(ROOT, abs).split(sep).join('/');
28	    if (rel === REPORT) continue;
29	    files.set(rel, readFileSync(abs, 'utf8'));
30	  }
31	  return files;
32	}
33	
34	test(`${REPORT} is current with the tree`, () => {
35	  const files = treeText();
36	  assert.ok(files.size > 100, `only ${files.size} files read — a partial checkout cannot judge a surface`);
37	
38	  const rendered = renderSurfaceReport({ packDir: PACK_DIR, files });
39	  const modules = readSurfaceUse({ files, packDir: PACK_DIR });
40	  assert.ok(modules.size >= 20, `only ${modules.size} public/ modules found — the folder's scope has moved out from under this test`);
41	
42	  const path = join(ROOT, REPORT);
43	  if (!process.env.CI && (!existsSync(path) || readFileSync(path, 'utf8') !== rendered)) writeFileSync(path, rendered);
44	  assert.ok(existsSync(path), `${REPORT} is missing — run this test locally (it regenerates the file) and commit the result`);
45	  assert.equal(
46	    readFileSync(path, 'utf8'), rendered,
47	    `${REPORT} is stale — run this test locally (it regenerates the file) and commit the result in the same change that moved the surface`,
48	  );
49	});
50	
51	// The scope assertion has to fail loudly: a packDir left behind by a layout change
52	// matches no module, and an empty report reads as "this pack publishes nothing".
53	test('a pack directory with no public/ modules is an error, not an empty report', () => {
54	  assert.throws(
55	    () => readSurfaceUse({ files: new Map([['packs/elsewhere/src/a.mjs', 'export const a = 1;']]), packDir: 'packs/nothing-here' }),
56	    /no public\/ modules found/,
57	  );
58	});
59	
60	test('publishedNames reads every export form, and the alias is what the outside sees', () => {
61	  const { names, wildcards } = publishedNames([
62	    "export { a, b as renamed } from '../src/one.mjs';",
63	    'export {',
64	    '  wrapped, alsoWrapped,',
65	    "} from '../src/two.mjs';",
66	    'export const CONST = 1;',
67	    'export function fn() {}',
68	    'export class Klass {}',
69	  ].join('\n'));
70	  assert.deepEqual(names, ['CONST', 'Klass', 'a', 'alsoWrapped', 'fn', 'renamed', 'wrapped']);
71	  assert.deepEqual(wildcards, []);
72	});
73	
74	// A star is reported as a star. Expanding it into the target's current names would
75	// print a promise the folder never made — the whole point of flagging it.
76	test('publishedNames keeps a wildcard separate from the names beside it', () => {
77	  const { names, wildcards } = publishedNames("export * from '../src/loop.mjs';\nexport { runIt } from '../src/loop.mjs';");
78	  assert.deepEqual(names, ['runIt']);
79	  assert.deepEqual(wildcards, ['../src/loop.mjs']);
80	  assert.deepEqual(publishedNames("export * as ns from '../src/loop.mjs';"), { names: ['ns'], wildcards: [] });
81	});
82	
83	test('consumerBucket separates a live dependency from the canon proving its own contract', () => {
84	  const b = (p) => consumerBucket(p, PACK_DIR);
85	  assert.equal(b('.github/workflows/claudinite-executor.yml'), 'workflow');
86	  assert.equal(b('packs/claudinite-dashboard/src/derive/board.mjs'), 'pack');
87	  assert.equal(b('packs/claudinite-dashboard/test/board.test.mjs'), 'pack (test)');
88	  assert.equal(b('.claudinite/local/packs/claudinite/RULES.md'), 'pack');
89	  assert.equal(b('bootstrap.md'), 'canon');
90	  assert.equal(b('engine-tests/migrations.test.mjs'), 'canon (test)');
91	  assert.equal(b(`${PACK_DIR}/src/execute/loop.mjs`), 'own pack');
92	});
93	
94	// Three spellings reach one module — a sibling pack's relative path, a member's mount
95	// path, and the pack's own — and all three have to land on the same row, or the report
96	// undercounts exactly the consumers that cannot be rewritten from here.
