// How a line reaches the module. A comment naming a path is a MENTION, not a
// dependency: it breaks nothing when the surface moves, and counting it as a reader
// overstates who the promise is being kept for — which is the one number this report
// exists to get right. A `node <path>` line runs the module and takes no name; an
// `import` takes names.
function reachOf(line) {
  if (/^\s*(?:\/\/|\*|#|\|)/.test(line)) return { kind: 'mention', names: [] };
  const braces = line.match(/(?:import|export)\s*\{([^}]*)\}\s*from/) || line.match(/\{([^}]*)\}\s*=\s*await\s+import/);
  if (braces) return { kind: 'import', names: braces[1].split(',').map((p) => p.trim().match(/^([\w$]+)/)?.[1]).filter(Boolean) };
  if (/(?:^|\s)(?:import|export)\s[^{]*from\s*['"]/.test(line) || /\bimport\s*\(/.test(line)) return { kind: 'import', names: [] };
  if (/(?:^|\s)node\s/.test(line)) return { kind: 'run', names: [] };
  return { kind: 'mention', names: [] };
}

