const {readSurfaceUse}=await import('./packs/claudinite-canon-curation/pack-surface.mjs');
const {readdirSync,readFileSync}=await import('node:fs');
const {join,relative,sep}=await import('node:path');
const SKIP=new Set(['.git','node_modules','.claudinite-cache']);
const files=new Map();
(function w(d){for(const e of readdirSync(d,{withFileTypes:true})){if(SKIP.has(e.name))continue;const a=join(d,e.name);if(e.isDirectory()){w(a);continue;}if(!/\.(mjs|js|json|md|yml|yaml)\$/.test(e.name))continue;const r=relative('.',a).split(sep).join('/');if(r.endsWith('SURFACE.GENERATED.md')||r.endsWith('pack-surface.test.mjs'))continue;files.set(r,readFileSync(a,'utf8'));}})('.');
const mods=readSurfaceUse({files,packDir:'packs/claudinite-tasks'});
const paths=new Set();
for(const m of mods.values()){for(const s of m.consumers.values())for(const p of s)paths.add(p);for(const p of m.mentions)paths.add(p);}
const inside=[...paths].filter(p=>p.startsWith('packs/claudinite-tasks/'));
console.log('distinct referencing files counted:', paths.size);
console.log('of those, inside claudinite-tasks:', inside.length, inside.length?inside:'(none)');
console.log('any counted path spelling the mount:', [...paths].filter(p=>p.includes('.claudinite/shared/')).length);
" 2>&1

