// Per-ELEMENT consumer map for packs/claudinite-tasks/public/: who takes each name,
// what kind of thing it is, and from where. Analysis only — writes nothing to the repo.
import { readdirSync, readFileSync } from 'node:fs';
import { join, relative, sep, dirname, resolve } from 'node:path';

const ROOT = '/home/user/Claudinite';
const PACK = 'packs/claudinite-tasks';
const PUB = `${PACK}/public/`;
const SKIP = new Set(['.git', 'node_modules', '.claudinite-cache']);

const files = new Map();
(function walk(d) {
  for (const e of readdirSync(d, { withFileTypes: true })) {
    if (SKIP.has(e.name)) continue;
    const a = join(d, e.name);
    if (e.isDirectory()) { walk(a); continue; }
    if (!/\.(mjs|js|json|md|yml|yaml)$/.test(e.name)) continue;
    const r = relative(ROOT, a).split(sep).join('/');
    if (r.endsWith('SURFACE.GENERATED.md') || r.endsWith('pack-surface.test.mjs')) continue;
    files.set(r, readFileSync(a, 'utf8'));
  }
})(ROOT);

function fold(text) {
  const L = text.split('\n'); const out = [];
  for (let i = 0; i < L.length; i++) { let l = L[i]; while (/^\s*(?:import|export)\s*\{/.test(l) && !l.includes('}') && i + 1 < L.length) l += ' ' + L[++i].trim(); out.push(l); }
  return out;
}
const splitNames = (s) => s.split(',').map(x => x.trim().match(/^([\w$]+)(?:\s+as\s+([\w$]+))?$/)).filter(Boolean);

// public export -> { origin file, original name }
const surface = new Map();
for (const [p, t] of files) {
  if (!p.startsWith(PUB) || !p.endsWith('.mjs')) continue;
  const mod = p.slice(PUB.length);
  for (const l of fold(t)) {
    const m = l.match(/^export\s*\{([^}]*)\}\s*from\s*['"]([^'"]+)['"]/);
    if (m) { const tgt = relative(ROOT, resolve(ROOT, dirname(p), m[2])).split(sep).join('/');
      for (const n of splitNames(m[1])) surface.set(`${mod}#${n[2] || n[1]}`, { mod, pub: n[2] || n[1], file: tgt, orig: n[1] }); }
    const s = l.match(/^export\s*\*\s*from\s*['"]([^'"]+)['"]/);
    if (s) { const tgt = relative(ROOT, resolve(ROOT, dirname(p), s[1])).split(sep).join('/');
      for (const l2 of fold(files.get(tgt) || '')) {
        const d = l2.match(/^export\s+(?:async\s+)?(?:function\s*\*?\s*([\w$]+)|class\s+([\w$]+)|(?:const|let|var)\s+([\w$]+))/);
        const n2 = d && (d[1] || d[2] || d[3]);
        if (n2 && !surface.has(`${mod}#${n2}`)) surface.set(`${mod}#${n2}`, { mod, pub: n2, file: tgt, orig: n2, viaStar: true });
      } }
  }
}

// kind, read off the ORIGIN declaration
function kindOf({ file, orig }) {
  const t = files.get(file); if (!t) return 'unknown';
  const L = t.split('\n');
  for (let i = 0; i < L.length; i++) {
    const m = L[i].match(new RegExp(`^export\\s+(?:async\\s+)?(function\\s*\\*?\\s*|class\\s+|const\\s+|let\\s+|var\\s+)${orig}\\b`));
    if (!m) continue;
    if (/function/.test(m[1])) return 'function';
    if (/class/.test(m[1])) return 'class';
    const rhs = L[i].slice(L[i].indexOf('=') + 1).trim();
    if (/^(?:async\s*)?(?:\(|[\w$]+\s*=>)/.test(rhs)) return 'function';
    if (/^\[/.test(rhs) || /^new Set/.test(rhs)) return 'set/list';
    if (/^\{/.test(rhs) || /^new Map/.test(rhs)) return 'map/record';
    if (/^['"`]/.test(rhs)) return 'string';
    if (/^\d|\*|\+|\d\s*\*/.test(rhs)) return 'number';
    return 'value';
  }
  return 'unknown';
}

// external takers, per name
const takers = new Map(); // "mod#name" -> Map(file -> bucket)
const modLevel = new Map(); // mod -> Map(file -> bucket) for whole-module reach
const bucketOf = (p) => {
  const q = p.replace(/^\.claudinite\/(?:shared|local)\//, '');
  if (q.startsWith(`${PACK}/`)) return null;
  if (q.endsWith('.yml') || q.endsWith('.yaml')) return 'workflow';
  const test = q.includes('/test/') || q.endsWith('.test.mjs');
  if (q.startsWith('packs/')) return test ? 'pack-test' : 'pack';
  return test ? 'canon-test' : 'canon';
};
const ref = new RegExp(`(?:claudinite-tasks/public/|(?:\\.\\./)+public/)([\\w.-]+)`, 'g');
for (const [p, t] of files) {
  const b = bucketOf(p); if (!b) continue;
  for (const l of fold(t)) {
    for (const m of l.matchAll(ref)) {
      const mod = m[1];
      const isProse = /^\s*(?:\/\/|\*|#|\|)/.test(l) || (!/(?:import|export)\s[^;]*from\s*['"]/.test(l) && !/import\s*\(/.test(l) && !/(?:^\s*|\brun:\s*)node\s/.test(l));
      if (isProse) continue;
      (modLevel.get(mod) ?? modLevel.set(mod, new Map()).get(mod)).set(p, b);
      const br = l.match(/(?:import|export)\s*\{([^}]*)\}\s*from/) || l.match(/\{([^}]*)\}\s*=\s*await\s+import/);
      if (!br) continue;
      for (const n of splitNames(br[1])) {
        const k = `${mod}#${n[1]}`;
        if (!surface.has(k)) continue;
        (takers.get(k) ?? takers.set(k, new Map()).get(k)).set(p, b);
      }
    }
  }
}

const packOf = (p) => { const q = p.replace(/^\.claudinite\/(?:shared|local)\//, ''); return q.startsWith('packs/') ? q.split('/')[1] : q.split('/')[0]; };

const mods = [...new Set([...surface.values()].map(s => s.mod))].sort();
for (const mod of mods) {
  const names = [...surface.values()].filter(s => s.mod === mod).sort((a, b) => a.pub.localeCompare(b.pub));
  const whole = modLevel.get(mod) ?? new Map();
  console.log(`\n### ${mod}   [module reached by: ${[...new Set([...whole].map(([f, b]) => `${packOf(f)}(${b})`))].sort().join(', ') || 'nobody'}]`);
  for (const s of names) {
    const t = takers.get(`${mod}#${s.pub}`) ?? new Map();
    const who = [...t].map(([f, b]) => `${f}[${b}]`).sort();
    console.log(`  ${s.pub.padEnd(30)} ${kindOf(s).padEnd(12)} ${s.viaStar ? '(via *) ' : ''}${who.length ? who.join('  ') : '— UNUSED'}`);
  }
}

// aggregate
console.log('\n\n===== AGGREGATE BY ELEMENT KIND =====');
const agg = {};
for (const s of surface.values()) {
  const k = kindOf(s); const t = takers.get(`${s.mod}#${s.pub}`) ?? new Map();
  (agg[k] ??= { total: 0, used: 0, prodUsed: 0, takerFiles: new Set(), takerPacks: new Set() });
  agg[k].total++;
  if (t.size) { agg[k].used++; if ([...t.values()].some(b => b === 'pack' || b === 'workflow' || b === 'canon')) agg[k].prodUsed++; }
  for (const [f, b] of t) { agg[k].takerFiles.add(f); agg[k].takerPacks.add(packOf(f)); }
