import { rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { deliveryForText, pullCreateError, landDelivery } from './land-pr.mjs';
import { SETTINGS_FILES } from '../../../../engine/settings-file.mjs';
import { withTaskTrailer } from '../contract/task-trailer.mjs';
import { restCall } from '../world/github.mjs';
import { runGit } from '../world/processes.mjs';
import { nowMs } from '../world/clock.mjs';
