export function orderTaskKeys(decl) {
  const rank = (k) => { const i = KEY_ORDER.indexOf(k); return i === -1 ? KEY_ORDER.length : i; };
  return Object.fromEntries(Object.entries(decl).sort(([a], [b]) => rank(a) - rank(b)));
