}
// THE DEFAULTS, and the one place a declaration's absent field becomes a value,
// so nothing downstream ever reads an undefined one (owner, 2026-09-03):
//   - `automerge`: land nothing unreviewed — `'nothing'`, for a task that may open a PR
//     (every outcome but `no_code_changes`).
//   - `agent_model`: no agent — `'none'`.
//   - `code_work`: no code work; `agent_instructions`: none.
// Neither timeout has a default, deliberately: an agent or a code-work
// subprocess always carries its own time limit, so the field is required
// wherever the phase it bounds is declared. `preconditions` and `expected_outcome`
// have no default either — each is a choice the author makes: the expression is
// the whole of when the task runs (docs/PRINCIPLES.md), and an absent one has
// not said.
// A task that declares a field keeps it; only an absent one is filled.
export const DEFAULT_AUTOMERGE = 'nothing';
export const DEFAULT_AGENT_MODEL = 'none';

// Fill the absent fields in place and return the declaration.
export function applyTaskDefaults(out) {
  if (out.agent_model === undefined) out.agent_model = DEFAULT_AGENT_MODEL;
  if (out.expected_outcome !== undefined && out.expected_outcome !== 'no_code_changes' && out.automerge === undefined) out.automerge = DEFAULT_AUTOMERGE;
  return out;
}
// The merged-PR fields, derived. Pure by construction and separated from the listing
// that fetches them ([`read-prs.mjs`](read-prs.mjs)) for the same reason the fold's
// counting core is separated from its worker — and for one more: these two are the
// only part of the merged-PR read another pack needs, and they are published through
// `public/` to a PAGE that runs in a browser, where a module reaching for
// `process.env` or a node builtin does not load at all.

// The closing keyword GitHub itself acts on, which is also what this repo's lifecycle
// asks a PR body to carry. The FIRST match wins: a PR closing several issues has one
// issue it is *for*, and it is the one named first.
const CLOSES_RE = /(?:^|\n)[^\S\n]*(?:closes|fixes|resolves)[^\S\n]+#(\d+)\b/i;

export function closesIssueIn(body) {
  const n = Number(CLOSES_RE.exec(String(body ?? ''))?.[1]);
  return Number.isFinite(n) && n > 0 ? n : null;
}

// A span in hours, to one decimal. Absent at either end is `null` — an unknown lead
// time, which is not a zero one — and so is a span whose ends arrive in the wrong
// order, which says the two clocks disagree rather than that the work took less than
// no time.
export function hoursBetween(from, to) {
  if (!from || !to) return null;
  const hours = (Date.parse(to) - Date.parse(from)) / 3600000;
  if (!Number.isFinite(hours) || hours < 0) return null;
  return Math.round(hours * 10) / 10;
}

