    format: 'json',
    error,
    object: obj,
    code,
    has: (key) => value(key) !== undefined,
    scalar: (key) => (['string', 'number', 'boolean'].includes(typeof value(key)) ? value(key) : undefined),
    list: (key) => {
      const v = value(key);
