// task (which hides the chain: an approval park is nothing without the PR it holds) and
// never a kind (which puts the two ends of one `Blocked-by` edge in different rows,
// and the edge is the finding).

import {
  isQueueItem, parseWorkItemBody, parseWorkItemTitle, outcomeOf, statusOf, labelNames,
  STATUS_NEEDS_HUMAN_APPROVAL, STATUS_NEEDS_HUMAN_FAILURE,
  STATUS_RUNNING_AGENT, STATUS_RUNNING_EXECUTOR, STATUS_READY,
  PARK_PREFIX, PARK_KINDS, ORIGIN_AD_HOC,
} from '../../../claudinite-tasks/public/work-items.mjs';
// Namespace-read for the one export that may be newer than the member's queue
// module: the dashboard and claudinite-tasks converge on separate cadences, so a
// named import of an export it has not reached yet is a link-time fault that takes
// the whole page. Before `manual` arrives, `ad-hoc` alone is what this meant.
import * as queueVocabulary from '../../../claudinite-tasks/public/work-items.mjs';
import { nextAnchor } from '../../../claudinite-tasks/public/anchors.mjs';

// Every origin a person's action produces, as against the schedule's own.
const askedForOrigins = () => queueVocabulary.ASKED_FOR_ORIGINS ?? [ORIGIN_AD_HOC];

const DAY = 86400e3;

// SEVEN BACK, TODAY, FOUR AHEAD. Four days ahead is the honest horizon — past it every
// prediction is "the same daily ticks again" — and seven back is the week of record the
// ledger above compares, which is what gives the task grid a past beside its future.
export const DAYS_BACK = 7;
### model
// Those engine modules are pure ESM with no `node:` imports, which is the property
// this file depends on and `browser-graph.test.mjs` pins across the page's whole
// import graph. Living inside `packs/claudinite-tasks/` makes the queue modules siblings,
// so the dashboard sits beside the mechanism it renders rather than reaching across
// the tree at it.

import { parseTaskDeclaration, applyTaskDefaults } from '../../../claudinite-tasks/public/task-declaration.mjs';
import {
  mostRecentAnchor, nextAnchor, periodMs, taskPeriodMs, cadenceOf, cadenceTermFor, holdsOnFailure, holdsOnAnyPark, statesConditions,
  DUE_TERM, ELAPSED_TERM,
} from '../../../claudinite-tasks/public/anchors.mjs';
import {
  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
} from '../../../claudinite-tasks/public/work-items.mjs';
import {
  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
  outcomeOf as decodeOutcome,
  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
  statusesOn, isParked, parkKindOf, triageLabelFor,
